              "note_page_name": "寄附者通知管理｜ふるさと納税do",
              "note_page_url": "https://do3.do-furusato.com/send-mail-list",
              "note_icon_type": 4,
              "note_icon_size": 0,
              "note_icon_color_type": 1,
